"""Writes kaggle/cells_stage_a/cell1_setup.py with scripts/datasets/{decontam,stage_a}.py embedded (re-run after
editing either module, so the notebook always carries the tested code)."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
mods = {name: (ROOT / "scripts" / "datasets" / name).read_text() for name in ("decontam.py", "stage_a.py")}
cell = '''# 1. STAGE A setup (CPU session, INTERNET ON, no GPU). Writes the data-prep code to /kaggle/working/code and checks
#    the tools it needs. Generated by scripts/datasets/make_stage_a_cells.py from the tested repo modules.
import importlib.util, os, shutil, subprocess, sys, urllib.request
from pathlib import Path

CODE = Path('/kaggle/working/code')
CODE.mkdir(parents=True, exist_ok=True)
FILES = {
'''
for name, text in mods.items():
    cell += f"    {name!r}: {text!r},\n"
cell += '''}
for name, text in FILES.items():
    (CODE / name).write_text(text)
for pkg in ('huggingface_hub', 'pyarrow'):
    if importlib.util.find_spec(pkg) is None:
        subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', pkg], check=True)
assert shutil.which('git'), 'git is needed for the workspace trees'
try:
    urllib.request.urlopen('https://huggingface.co', timeout=20)
except Exception as e:
    raise SystemExit(f'No internet: turn it on in the notebook settings ({e})')
r = subprocess.run([sys.executable, str(CODE / 'decontam.py'), '--test'], capture_output=True, text=True)
print(r.stdout.strip() or r.stderr[-500:])
print('code written to', CODE, '| ready')
'''
(ROOT / "kaggle" / "cells_stage_a" / "cell1_setup.py").write_text(cell)
print("wrote kaggle/cells_stage_a/cell1_setup.py")
